own pathway definitions you need to translate it into a dataframe where for every gene in a given pathway there is a row with the pathway name and the gene. In order to generate an enrichment plot with enrichplot we need the fgsea results in the datastructure returned by clusterProfiler. To run fGSEA in this way we need: the ranks file, as before the pathways as a data frame. Below we show how to run fGSEA using the clusterProfiler package and user supplied pathway definitions. #translate our gmt file (a named list of genesets) into a dataframe #with one row per gene in each pathway. TERMS &lt;- data.frame( name = rep(names(pathways), lengths(pathways)), gene = unlist(pathways, use.names = FALSE) ) # specify the gene ranks, and make sure it is in descending order. gsea_scores &lt;- ranks gsea_scores &lt;- gsea_scores[!is.na(gsea_scores)] gsea_scores &lt;- sort(gsea_scores, decreasing = TRUE) # Set a seed for reproducibility set.seed(123) #Run fgsea using clusterProfiler, with the same gene-set size limits as above. selected_gsea &lt;- clusterProfiler::GSEA( geneList = gsea_scores, TERM2GENE = TERMS, minGSSize = 10, maxGSSize = 500, pvalueCutoff = 1, verbose = FALSE, pAdjustMethod = &quot;fdr&quot;, scoreType = &quot;std&quot;, eps = 0 ) ## Warning in preparePathwaysAndStats(pathways, stats, minSize, maxSize, gseaParam, : There are ties in the preranked stats (0.01% of the list). ## The order of those tied genes will be arbitrary, which may produce unexpected results. Print out a few of the top enrichment plots all_figures &lt;- list() #generate GSEA plots for the top Parental (down-regulated) genesets that we have already seen in the table above rows_to_use &lt;- which(selected_gsea@result$ID %in% topPathwaysDown) for(i in seq_along(rows_to_use)){ row_number = rows_to_use[i] #format the title for the enrichment plot pw_des &lt;- selected_gsea@result$Description[row_number] pw_pval &lt;- selected_gsea@result$pvalue[row_number] pw_pval &lt;- format(pw_pval, scientific = F, digits = 3) pw_qval &lt;- selected_gsea@result$p.adjust[row_number] pw_qval &lt;- format(pw_qval, scientific = F, digits = 3) pw_nes &lt;- selected_gsea@result$NES[row_number] pw_nes &lt;- format(pw_nes, scientific = F, digits = 2) pw_es &lt;- selected_gsea@result$enrichmentScore[row_number] pw_es &lt;- format(pw_es, scientific = F, digits = 2) mytitle &lt;- glue::glue(&#39;{pw_des}
(pval: {pw_pval}, qval: {pw_qval}, NES: {pw_nes}, ES: {pw_es})&#39;) figure &lt;- enrichplot::gseaplot2( selected_gsea, geneSetID = selected_gsea@result$ID[row_number], title = mytitle, color = &quot;green2&quot;, base_size = 12, rel_heights = c(1.5, 0.5, 1), subplots = 1:3, pvalue_table = F, ES_geom = &quot;line&quot; ) all_figures[[i]] &lt;- figure } ## Warning: `aes_()` was deprecated in ggplot2 3.0.0. ## ℹ Please use tidy evaluation idioms with `aes()` ## ℹ The deprecated feature was likely used in the enrichplot package. ## Please report the issue at ## &lt;https://github.com/GuangchuangYu/enrichplot/issues&gt;. ## This warning is displayed once per session. ## Call `lifecycle::last_lifecycle_warnings()` to see where this warning was ## generated. #display the first 3 enrichment plots for (figure in head(all_figures, 3)) { print(figure) } 0.18.5.2 Bar plots top pathways associated with Parental topPathwaysDown &lt;- fgseaRes[ES &lt; 0][head(order(pval), n=20), pathway] enrichment_results_topdown &lt;- fgseaRes[which(fgseaRes$pathway %in% topPathwaysDown),] #change the name to be just the first part of the name enrichment_results_topdown$pathway &lt;- unlist(lapply(enrichment_results_topdown$pathway, FUN=function(x){unlist(strsplit(x,split = &quot;%&quot;))[1]})) #make sure that names are unique after shortening them (the same name can come from different databases) enrichment_results_topdown$pathway &lt;- make.unique(enrichment_results_topdown$pathway) ##Calculate a score: the absolute value of the NES. ##(the pvalues of the top pathways are all very close to each other, so the NES is more informative here) enrichment_results_topdown$score = abs(enrichment_results_topdown$NES) enrichmentTidy &lt;- enrichment_results_topdown %&gt;% as_tibble() %&gt;% arrange(desc(score)) %&gt;% slice_head(n = 20) p = ggplot(enrichmentTidy, aes(reorder(pathway, score), score)) + geom_col(aes(fill = score), width=0.8) + scale_fill_gradient(low = &quot;#C1F6F8&quot;, high = &quot;#